/* AIVIC_FUNCTION_BUNDLE_START owner=generateMultiConstraintMeals exports=generateMultiConstraintMeals */
const __aivicBundle_13_generateMultiConstraintMeals = (() => {
  function generateMultiConstraintMeals(input: {
    constraints: MealConstraints;
    priorityOrder?: Record<string, number>;
    candidateMenus?: MealCandidate[];
    familyMembers?: any[];
  }): {
    rankedCandidates: RankedMealProposal[];
    excludedCandidates: MealCandidate[];
    constraintFulfillmentScores: ConstraintFulfillmentScores;
    totalEvaluationScore: number;
    mealCandidates?: Array<{
      memberId?: string;
      priorityLevel: number;
      satisfactionScore: number;
      totalCalories: number;
      ingredients: string[];
      cookingTimeMinutes: number;
    }>;
  } {
    const {
      constraints,
      priorityOrder = {},
      candidateMenus = [],
      familyMembers = [],
    } = input;
  
    const allAllergyExclusions = new Set<string>();
    if (constraints.allergyExclusions) {
      constraints.allergyExclusions.forEach((a) => allAllergyExclusions.add(a));
    }
    familyMembers.forEach((member) => {
      if (member.allergies && Array.isArray(member.allergies)) {
        member.allergies.forEach((allergy: string) =>
          allAllergyExclusions.add(allergy)
        );
      }
    });
  
    const rankedCandidates: RankedMealProposal[] = [];
    const excludedCandidates: MealCandidate[] = [];
    const mealCandidatesForTest: Array<{
      memberId?: string;
      priorityLevel: number;
      satisfactionScore: number;
      totalCalories: number;
      ingredients: string[];
      cookingTimeMinutes: number;
    }> = [];
  
    const calorieLimit = constraints.calorieLimit ?? Infinity;
    const cookingTimeLimit = constraints.cookingTimeLimit ?? Infinity;
    const budgetLimit = constraints.budgetLimit ?? Infinity;
  
    candidateMenus.forEach((candidate) => {
      const meetsCalorie =
        candidate.calories <= calorieLimit || calorieLimit === Infinity;
      const meetsCookingTime =
        candidate.cookingTime <= cookingTimeLimit || cookingTimeLimit === Infinity;
      const meetsBudget =
        candidate.budget <= budgetLimit || budgetLimit === Infinity;
  
      const hasAllergyConflict =
        candidate.allergyRisks &&
        candidate.allergyRisks.some((risk) => allAllergyExclusions.has(risk));
  
      if (meetsCalorie && meetsCookingTime && meetsBudget && !hasAllergyConflict) {
        const priorityLevel = priorityOrder[candidate.id] ?? 0;
  
        rankedCandidates.push({
          id: candidate.id,
          name: candidate.name,
          satisfactionScore: candidate.satisfactionScore,
          calories: candidate.calories,
          cookingTime: candidate.cookingTime,
          budget: candidate.budget,
          allergyRisks: candidate.allergyRisks,
        });
  
        mealCandidatesForTest.push({
          priorityLevel,
          satisfactionScore: candidate.satisfactionScore,
          totalCalories: candidate.calories,
          ingredients: [],
          cookingTimeMinutes: candidate.cookingTime,
        });
      } else {
        excludedCandidates.push(candidate);
      }
    });
  
    rankedCandidates.sort((a, b) => {
      const priorityA = priorityOrder[a.id] ?? 0;
      const priorityB = priorityOrder[b.id] ?? 0;
  
      if (priorityA !== priorityB) {
        return priorityA - priorityB;
      }
  
      return a.satisfactionScore - b.satisfactionScore;
    });
  
    mealCandidatesForTest.sort((a, b) => {
      if (a.priorityLevel !== b.priorityLevel) {
        return a.priorityLevel - b.priorityLevel;
      }
      return a.satisfactionScore - b.satisfactionScore;
    });
  
    const constraintFulfillmentScores: ConstraintFulfillmentScores = {
      calorie: rankedCandidates.length > 0 ? 1.0 : 0.0,
      budget: rankedCandidates.length > 0 ? 1.0 : 0.0,
      cookingTime: rankedCandidates.length > 0 ? 1.0 : 0.0,
      allergy: rankedCandidates.length > 0 ? 1.0 : 0.0,
    };
  
    const totalEvaluationScore =
      rankedCandidates.length > 0
        ? rankedCandidates.reduce((sum, meal) => sum + meal.satisfactionScore, 0) /
          rankedCandidates.length
        : 0;
  
    return {
      rankedCandidates,
      excludedCandidates,
      constraintFulfillmentScores,
      totalEvaluationScore,
      mealCandidates: mealCandidatesForTest,
    };
  }
  return { generateMultiConstraintMeals };
})();
export const generateMultiConstraintMeals = __aivicBundle_13_generateMultiConstraintMeals.generateMultiConstraintMeals;
