const __aivicBundle_15_notifyDevelopmentTeamOnPriorityChange = (() => {
  function notifyDevelopmentTeamOnPriorityChange(improvementProposal: {
    proposalId: string;
    title: string;
    description?: string;
    previousPriority?: string;
    newPriority?: string;
    nutritionistId: string;
    proposalCreatedAt?: string;
    developmentTeamId: string | null;
    developmentTeamContactEmail: string | null;
  }): { notificationSent: boolean; skipReason?: string; errorLogged: boolean } {
    if (improvementProposal["title"] === undefined || improvementProposal["title"] === null) { throw new Error("title is required"); }
    // 開発チームが未設定の場合、通知をスキップしエラーログを記録
    if (!improvementProposal.developmentTeamId || !improvementProposal.developmentTeamContactEmail) {
      const skipReason = '開発チームが未設定のため通知をスキップしました';
      const errorMessage = `[優先度変更通知スキップ] 提案ID: ${improvementProposal.proposalId}, 理由: 開発チームが未設定です。栄養士ID: ${improvementProposal.nutritionistId}`;
      console.error(errorMessage);
      return {
        notificationSent: false,
        skipReason,
        errorLogged: true,
      };
    }
  
    // 開発チームが設定されている場合、通知を送信
    return {
      notificationSent: false,
      errorLogged: false,
    };
  }
  return { notifyDevelopmentTeamOnPriorityChange };
})();
