/* AIVIC_FUNCTION_BUNDLE_START owner=compareAlgorithmImprovementQuantitatively exports=compareAlgorithmImprovementQuantitatively */
const __aivicBundle_20_compareAlgorithmImprovementQuantitatively = (() => {
  function compareAlgorithmImprovementQuantitatively(input: {
    beforeAlgorithmDataSet: Array<{
      mealGenerationId: string;
      timestamp: Date;
      satisfactionScore: number;
      completionRate: number;
      rejectionRate: number;
      cookingTimeMinutes: number;
      algorithmVersion: string;
    }>;
    afterAlgorithmDataSet: Array<{
      mealGenerationId: string;
      timestamp: Date;
      satisfactionScore: number;
      completionRate: number;
      rejectionRate: number;
      cookingTimeMinutes: number;
      algorithmVersion: string;
    }>;
    beforePeriodStartDate: Date;
    beforePeriodEndDate: Date;
    afterPeriodStartDate: Date;
    afterPeriodEndDate: Date;
    minimumDataRequirementDays: number;
  }): {
    isAggregatable: boolean;
    errorMessage?: string;
    aggregatedComparison?: Record<string, any>;
    dataCollectionDaysBefore: number;
    dataCollectionDaysAfter: number;
  } {
    const calculateDaysDifference = (startDate: Date, endDate: Date): number => {
      const timeDiff = endDate.getTime() - startDate.getTime();
      const daysDiff = Math.ceil(timeDiff / (1000 * 60 * 60 * 24));
      return daysDiff;
    };
  
    const dataCollectionDaysBefore = calculateDaysDifference(
      input.beforePeriodStartDate,
      input.beforePeriodEndDate
    );
  
    const dataCollectionDaysAfter = calculateDaysDifference(
      input.afterPeriodStartDate,
      input.afterPeriodEndDate
    );
  
    const isAggregatable =
      dataCollectionDaysBefore >= input.minimumDataRequirementDays &&
      dataCollectionDaysAfter >= input.minimumDataRequirementDays;
  
    if (!isAggregatable) {
      return {
        isAggregatable: false,
        errorMessage: `データ期間が不足しています。改善前: ${dataCollectionDaysBefore}日, 改善後: ${dataCollectionDaysAfter}日。1週間以上のデータが必要です。`,
        dataCollectionDaysBefore,
        dataCollectionDaysAfter
      };
    }
  
    const calculateMetrics = (
      dataSet: Array<{
        satisfactionScore: number;
        completionRate: number;
        rejectionRate: number;
        cookingTimeMinutes: number;
      }>
    ) => {
      if (dataSet.length === 0) {
        return {
          avgSatisfactionScore: 0,
          avgCompletionRate: 0,
          avgRejectionRate: 0,
          avgCookingTimeMinutes: 0
        };
      }
  
      const sumSatisfaction = dataSet.reduce((sum, item) => sum + item.satisfactionScore, 0);
      const sumCompletion = dataSet.reduce((sum, item) => sum + item.completionRate, 0);
      const sumRejection = dataSet.reduce((sum, item) => sum + item.rejectionRate, 0);
      const sumCookingTime = dataSet.reduce((sum, item) => sum + item.cookingTimeMinutes, 0);
  
      return {
        avgSatisfactionScore: sumSatisfaction / dataSet.length,
        avgCompletionRate: sumCompletion / dataSet.length,
        avgRejectionRate: sumRejection / dataSet.length,
        avgCookingTimeMinutes: sumCookingTime / dataSet.length
      };
    };
  
    const beforeMetrics = calculateMetrics(input.beforeAlgorithmDataSet);
    const afterMetrics = calculateMetrics(input.afterAlgorithmDataSet);
  
    const aggregatedComparison: Record<string, any> = {
      beforeAlgorithm: {
        dataCount: input.beforeAlgorithmDataSet.length,
        ...beforeMetrics
      },
      afterAlgorithm: {
        dataCount: input.afterAlgorithmDataSet.length,
        ...afterMetrics
      },
      improvements: {
        satisfactionScoreDifference: afterMetrics.avgSatisfactionScore - beforeMetrics.avgSatisfactionScore,
        completionRateDifference: afterMetrics.avgCompletionRate - beforeMetrics.avgCompletionRate,
        rejectionRateDifference: afterMetrics.avgRejectionRate - beforeMetrics.avgRejectionRate,
        cookingTimeReduction: beforeMetrics.avgCookingTimeMinutes - afterMetrics.avgCookingTimeMinutes
      }
    };
  
    return {
      isAggregatable: true,
      aggregatedComparison,
      dataCollectionDaysBefore,
      dataCollectionDaysAfter
    };
  }
  return { compareAlgorithmImprovementQuantitatively };
})();
export const compareAlgorithmImprovementQuantitatively = __aivicBundle_20_compareAlgorithmImprovementQuantitatively.compareAlgorithmImprovementQuantitatively;
/* AIVIC_FUNCTION_BUNDLE_END owner=compareAlgorithmImprovementQuantitatively */

/* AIVIC_FUNCTION_BUNDLE_START owner=calculateAlgorithmImprovementComparison exports=calculateAlgorithmImprovementComparison */
const __aivicBundle_21_calculateAlgorithmImprovementComparison = (() => {
  function calculateAlgorithmImprovementComparison(
    testData: Array<{
      algorithmVersionId: string;
      mealPlanId: string;
      cookingTimeReductionMinutes: number;
      satisfactionScore: number;
      completionRate: number;
      rejectionRate: number;
    }>
  ): {
    totalCookingTimeReductionMinutes: number;
    dataCount: number;
    averageCookingTimeReductionMinutes: number;
    averageSatisfactionScore: number;
    averageCompletionRate: number;
    averageRejectionRate: number;
    hasError: boolean;
  } {
    const dataCount = testData.length;
    let hasError = false;
  
    if (dataCount === 0) {
      return {
        totalCookingTimeReductionMinutes: 0,
        dataCount: 0,
        averageCookingTimeReductionMinutes: 0,
        averageSatisfactionScore: 0,
        averageCompletionRate: 0,
        averageRejectionRate: 0,
        hasError: false,
      };
    }
  
    let totalCookingTimeReductionMinutes = 0;
    let totalSatisfactionScore = 0;
    let totalCompletionRate = 0;
    let totalRejectionRate = 0;
  
    for (const item of testData) {
      totalCookingTimeReductionMinutes += item.cookingTimeReductionMinutes;
      totalSatisfactionScore += item.satisfactionScore;
      totalCompletionRate += item.completionRate;
      totalRejectionRate += item.rejectionRate;
    }
  
    const averageCookingTimeReductionMinutes =
      totalCookingTimeReductionMinutes / dataCount;
    const averageSatisfactionScore = totalSatisfactionScore / dataCount;
    const averageCompletionRate = totalCompletionRate / dataCount;
    const averageRejectionRate = totalRejectionRate / dataCount;
  
    if (
      Number.isNaN(averageCookingTimeReductionMinutes) ||
      Number.isNaN(averageSatisfactionScore) ||
      Number.isNaN(averageCompletionRate) ||
      Number.isNaN(averageRejectionRate)
    ) {
      hasError = true;
    }
  
    return {
      totalCookingTimeReductionMinutes,
      dataCount,
      averageCookingTimeReductionMinutes,
      averageSatisfactionScore,
      averageCompletionRate,
      averageRejectionRate,
      hasError,
    };
  }
  return { calculateAlgorithmImprovementComparison };
})();
