/* AIVIC_FUNCTION_BUNDLE_START owner=calculateFamilySatisfactionScore exports=calculateFamilySatisfactionScore */
const __aivicBundle_22_calculateFamilySatisfactionScore = (() => {
  function calculateFamilySatisfactionScore(familyGroup: {
    familyId: string;
    mealProposalId: string;
    familyMembers: Array<{
      memberId: string;
      name: string;
      satisfactionScore: number;
      timestamp: Date;
    }>;
  }): {
    averageScore: number;
    familyId: string;
    mealProposalId: string;
    memberCount: number;
  } {
    const { familyId, mealProposalId, familyMembers } = familyGroup;
  
    if (!familyMembers || familyMembers.length === 0) {
      throw new Error('家族成員が存在しません');
    }
  
    for (const member of familyMembers) {
      if (member.satisfactionScore < 1 || member.satisfactionScore > 5) {
        throw new Error('満足度スコアは1～5の範囲である必要があります');
      }
    }
  
    const totalScore = familyMembers.reduce(
      (sum, member) => sum + member.satisfactionScore,
      0
    );
    const averageScore = Math.round((totalScore / familyMembers.length) * 100) / 100;
  
    return {
      averageScore,
      familyId,
      mealProposalId,
      memberCount: familyMembers.length,
    };
  }
  return { calculateFamilySatisfactionScore };
})();
