/* AIVIC_FUNCTION_BUNDLE_START owner=validateMealPlans exports=validateMealPlans */
const __aivicBundle_25_validateMealPlans = (() => {
  function validateMealPlans(input: MealPlanValidationInput): {
    statusCode: number;
    isValid: boolean;
    mealValidations: MealValidationResult[];
    message: string;
  } {
    const mealValidations: MealValidationResult[] = [];
  
    // 家族構成から全制限条件とアレルギーを集約
    const allRestrictions = new Set<string>();
    const allAllergies = new Set<string>();
  
    for (const member of input.familyComposition.members) {
      if (member.restrictions) {
        member.restrictions.forEach((r) => allRestrictions.add(r));
      }
      if (member.allergies) {
        member.allergies.forEach((a) => allAllergies.add(a));
      }
    }
  
    const hasRestrictions = allRestrictions.size > 0 || allAllergies.size > 0;
  
    // 各献立プランを検証
    for (const mealPlan of input.mealPlans) {
      let restrictionCheckResult = "passed";
      let allergyCheckResult = "passed";
      let nutritionCheckResult = "passed";
      let isValidPlan = true;
  
      // 制限条件がある場合のみ詳細検証を実施
      if (hasRestrictions) {
        for (const meal of mealPlan.meals) {
          // アレルギーチェック
          for (const allergen of allAllergies) {
            if (
              meal.ingredients.some((ing) =>
                ing.toLowerCase().includes(allergen.toLowerCase())
              )
            ) {
              allergyCheckResult = "failed";
              isValidPlan = false;
              break;
            }
          }
  
          // 制限条件チェック
          for (const restriction of allRestrictions) {
            if (
              meal.ingredients.some((ing) =>
                ing.toLowerCase().includes(restriction.toLowerCase())
              )
            ) {
              restrictionCheckResult = "failed";
              isValidPlan = false;
              break;
            }
          }
  
          // 栄養情報チェック（存在確認）
          if (
            !meal.nutritionInfo ||
            meal.nutritionInfo.calories === undefined ||
            meal.nutritionInfo.protein === undefined ||
            meal.nutritionInfo.carbs === undefined ||
            meal.nutritionInfo.fat === undefined
          ) {
            nutritionCheckResult = "failed";
            isValidPlan = false;
          }
        }
      }
  
      mealValidations.push({
        isValid: isValidPlan,
        mealPlanId: mealPlan.mealPlanId,
        details: {
          restrictionCheck: restrictionCheckResult,
          allergyCheck: allergyCheckResult,
          nutritionCheck: nutritionCheckResult,
        },
      });
    }
  
    // 全献立が有効かどうかを判定
    const allValid = mealValidations.every((v) => v.isValid);
  
    // メッセージを決定
    let message: string;
    if (!hasRestrictions) {
      message = "制限条件がないため全ての献立が有効です";
    } else if (allValid) {
      message = "全ての献立が制限条件を満たしています";
    } else {
      message = "アレルギー対象食材が含まれています";
    }
  
    return {
      statusCode: allValid ? 200 : 400,
      isValid: allValid,
      mealValidations,
      message,
    };
  }
  return { validateMealPlans };
})();
export const validateMealPlans = __aivicBundle_25_validateMealPlans.validateMealPlans;
/* AIVIC_FUNCTION_BUNDLE_END owner=validateMealPlans */

/* AIVIC_FUNCTION_BUNDLE_START owner=validateMealPlanIntegrity exports=validateMealPlanIntegrity */
const __aivicBundle_26_validateMealPlanIntegrity = (() => {
  function validateMealPlanIntegrity(
    input: MealPlanIntegrityCheckInput
  ): MealPlanIntegrityResult {
    // 料理名の検証
    if (!input.mealName || input.mealName.trim() === '') {
      throw new Error('料理名が必須です');
    }
  
    // 栄養価情報の検証
    if (!input.nutritionInfo) {
      throw new Error('栄養価情報が必須です');
    }
  
    // 栄養素の完全性検証
    if (
      input.nutritionInfo.calories === null ||
      input.nutritionInfo.calories === undefined ||
      input.nutritionInfo.protein === null ||
      input.nutritionInfo.protein === undefined ||
      input.nutritionInfo.carbs === null ||
      input.nutritionInfo.carbs === undefined ||
      input.nutritionInfo.fat === null ||
      input.nutritionInfo.fat === undefined
    ) {
      throw new Error('栄養素が不完全です');
    }
  
    // 調理時間の検証
    if (
      input.cookingTimeMinutes === undefined ||
      input.cookingTimeMinutes === null
    ) {
      throw new Error('調理時間が必須です');
    }
  
    if (input.cookingTimeMinutes < 0) {
      throw new Error('調理時間は負の値にできません');
    }
  
    // 家族成員IDの検証
    if (!input.familyMemberId || input.familyMemberId.trim() === '') {
      throw new Error('家族成員IDが必須です');
    }
  
    // すべての検証に合格した場合、結果オブジェクトを返す
    const validationTimestamp = new Date().toISOString();
  
    const result: MealPlanIntegrityResult = {
      isValid: true,
      validationTimestamp,
      mealName: input.mealName,
      nutritionCheck: true,
      allergyCompliance: input.allergyCheckResult,
      dietaryRestrictionCompliance: input.dietaryRestrictionCheckResult,
      cookingTimeWithinLimit: input.cookingTimeMinutes >= 0,
    };
  
    return result;
  }
  return { validateMealPlanIntegrity };
})();
