    // Determine overall validation status
    const allVersionsDistributed = segmentIds.length > 0;
    const allSegmentsConsistent = Object.values(consistencyValidation).every((v) => v.isConsistent);
    const allVersionsIsolated = Object.values(versionIsolationValidation).every((v) => v.isDifferent || segmentIds.length === 1);
