const __aivicBundle_29_validateAlgorithmVersionDeployment = (() => {
  function validateAlgorithmVersionDeployment(
    input: AlgorithmVersionDeploymentInput
  ): AlgorithmVersionDeploymentResult {
    const { algorithmVersionId, verificationStartDate, verificationEndDate, targetUserSegments } = input;
  
    // Validate verificationStartDate
    if (!verificationStartDate || typeof verificationStartDate !== 'string' || verificationStartDate.trim() === '') {
      throw new Error('検証期間の開始日時が無効です');
    }
  
    const startDate = new Date(verificationStartDate);
    if (isNaN(startDate.getTime()) || verificationStartDate !== startDate.toISOString()) {
      throw new Error('検証期間の開始日時が無効です');
    }
  
    // Validate verificationEndDate
    if (!verificationEndDate || typeof verificationEndDate !== 'string' || verificationEndDate.trim() === '') {
      throw new Error('検証期間の終了日時が無効です');
    }
  
    const endDate = new Date(verificationEndDate);
    if (isNaN(endDate.getTime()) || verificationEndDate !== endDate.toISOString()) {
      throw new Error('検証期間の終了日時が無効です');
    }
  
    // Validate that startDate <= endDate
    if (startDate > endDate) {
      throw new Error('検証期間の開始日時は終了日時以前である必要があります');
    }
  
    return {
      isValid: true,
      algorithmVersionId,
      verificationStartDate,
      verificationEndDate,
      targetUserSegments,
      deploymentStatus: 'pending',
    };
  }
  return { validateAlgorithmVersionDeployment };
})();
