/* AIVIC_FUNCTION_BUNDLE_START owner=validateAndApplySalesPeriodRule exports=validateAndApplySalesPeriodRule */
const __aivicBundle_33_validateAndApplySalesPeriodRule = (() => {
  function validateAndApplySalesPeriodRule(
    mealData: any,
    rule: any
  ): {
    applied_discount_rate: number;
    season_pattern_applied: string | null;
    is_within_sales_period: boolean;
    adjusted_ingredient_price: number;
    rule_specification: {
      promotion_id: string;
      season_pattern: string;
      discount_rate: number;
      sales_period_start: string;
      sales_period_end: string;
    };
    is_valid_rule: boolean;
  } {
    const queryDate = new Date(mealData.query_date);
    const salesPeriodStart = new Date(rule.sales_period_start);
    const salesPeriodEnd = new Date(rule.sales_period_end);
  
    const isWithinPeriod =
      queryDate >= salesPeriodStart && queryDate <= salesPeriodEnd;
  
    const appliedDiscountRate = isWithinPeriod ? rule.discount_rate : 0;
    const seasonPatternApplied = isWithinPeriod ? rule.season_pattern : null;
  
    let adjustedIngredientPrice = 0;
    if (
      mealData.ingredients &&
      mealData.ingredients.length > 0
    ) {
      const firstIngredient = mealData.ingredients[0];
      const basePrice = firstIngredient.base_price;
      adjustedIngredientPrice = isWithinPeriod
        ? basePrice * (1 - appliedDiscountRate / 100)
        : basePrice;
    }
  
    const ruleSpecification = {
      promotion_id: rule.promotion_id,
      season_pattern: rule.season_pattern,
      discount_rate: rule.discount_rate,
      sales_period_start: salesPeriodStart.toISOString(),
      sales_period_end: salesPeriodEnd.toISOString(),
    };
  
    return {
      applied_discount_rate: appliedDiscountRate,
      season_pattern_applied: seasonPatternApplied,
      is_within_sales_period: isWithinPeriod,
      adjusted_ingredient_price: adjustedIngredientPrice,
      rule_specification: ruleSpecification,
      is_valid_rule: true,
    };
  }
  return { validateAndApplySalesPeriodRule };
})();
