    if (distributionConfig["ruleSpecificationFileName"] === undefined || distributionConfig["ruleSpecificationFileName"] === null) { throw new Error("ruleSpecificationFileName is required"); }
    if (distributionConfig["targetUserSegment"] === undefined || distributionConfig["targetUserSegment"] === null) { throw new Error("targetUserSegment is required"); }
