/* AIVIC_FUNCTION_BUNDLE_START owner=validateRuleSpecificationForApproval exports=validateRuleSpecificationForApproval */
const __aivicBundle_44_validateRuleSpecificationForApproval = (() => {
  function validateRuleSpecificationForApproval(ruleSpec: any): any {
    const validationTimestamp = new Date().toISOString();
  
    // 必須フィールドの検証
    const issues: string[] = [];
    const recommendations: string[] = [];
  
    // seasonal_pattern の検証
    if (!ruleSpec.seasonal_pattern || ruleSpec.seasonal_pattern.trim() === "") {
      issues.push("季節パターンが指定されていません");
      recommendations.push("季節パターンを入力してください");
    }
  
    // discount_rate_threshold の検証
    if (
      ruleSpec.discount_rate_threshold === null ||
      ruleSpec.discount_rate_threshold === undefined
    ) {
      issues.push("割引率閾値が指定されていません");
      recommendations.push("割引率閾値を数値で指定してください");
    }
  
    // sales_period の検証
    if (
      !ruleSpec.sales_period_start ||
      ruleSpec.sales_period_start.trim() === "" ||
      !ruleSpec.sales_period_end ||
      ruleSpec.sales_period_end.trim() === ""
    ) {
      issues.push("販売期間が指定されていません");
      recommendations.push("販売期間の開始日と終了日を指定してください");
    }
  
    // 必須フィールドが不足している場合はエラーをスロー
    if (issues.length > 0) {
      throw new Error(issues.join("; "));
    }
  
    // すべての必須フィールドが入力されている場合は承認フロー状態を遷移
    return {
      rule_spec_id: ruleSpec.rule_spec_id,
      seasonal_pattern: ruleSpec.seasonal_pattern,
      discount_rate_threshold: ruleSpec.discount_rate_threshold,
      sales_period_start: ruleSpec.sales_period_start,
      sales_period_end: ruleSpec.sales_period_end,
      approval_status: "pending_approval",
      approval_initiated_at: validationTimestamp,
    };
  }
  return { validateRuleSpecificationForApproval };
})();
