/* AIVIC_FUNCTION_BUNDLE_START owner=assignProxyParticipant exports=assignProxyParticipant */
const __aivicBundle_51_assignProxyParticipant = (() => {
  function assignProxyParticipant(input: {
    meeting_id: string;
    participants: Array<{
      participant_id: string;
      name: string;
      status: string;
      role: string;
    }>;
    proxy_candidate_id: string;
  }): {
    proxyAssignmentSuccessful: boolean;
    originalParticipant: MeetingParticipant;
    proxyParticipant: MeetingParticipant;
    assignmentReason: string;
    assignmentDate: string;
    validationErrors: string[];
  } {
    if (input["meeting_id"] === undefined || input["meeting_id"] === null) { throw new Error("meeting_id is required"); }
    const { participants, proxy_candidate_id } = input;
  
    const validationErrors: string[] = [];
  
    // Check if all participants are absent
    const allAbsent = participants.every((p) => p.status === 'absent');
    if (allAbsent) {
      throw new Error('全参加者が欠席しているため、代理参加者の割り当てができません');
    }
  
    // Find original participant (first confirmed/present participant)
    const originalParticipantData = participants.find(
      (p) => p.status !== 'absent'
    );
  
    if (!originalParticipantData) {
      validationErrors.push('割り当て対象の参加者が見つかりません');
    }
  
    // Find proxy candidate in participants list
    const proxyParticipantData = participants.find(
      (p) => p.participant_id === proxy_candidate_id
    );
  
    const assignmentDate = new Date().toISOString();
  
    // Build original participant object
    const originalParticipant: MeetingParticipant = {
      participantId: originalParticipantData?.participant_id || '',
      name: originalParticipantData?.name || '',
      role: originalParticipantData?.role || '',
      isConfirmed: originalParticipantData?.status === 'confirmed',
      confirmationDate:
        originalParticipantData?.status === 'confirmed'
          ? assignmentDate
          : undefined,
      isProxy: false,
      attendanceStatus:
        originalParticipantData?.status === 'absent'
          ? 'declined'
          : (originalParticipantData?.status as
              | 'confirmed'
              | 'pending'
              | 'declined'
              | 'proxy') || 'pending',
    };
  
    // Build proxy participant object
    const proxyParticipant: MeetingParticipant = {
      participantId: proxy_candidate_id,
      name: proxyParticipantData?.name || '',
      role: proxyParticipantData?.role || '',
      isConfirmed: proxyParticipantData?.status === 'confirmed',
      confirmationDate:
        proxyParticipantData?.status === 'confirmed'
          ? assignmentDate
          : undefined,
      isProxy: true,
      proxyForParticipantId: originalParticipantData?.participant_id,
      attendanceStatus:
        proxyParticipantData?.status === 'confirmed' ? 'proxy' : 'pending',
    };
  
    // Determine success: proxy must be confirmed
    const proxyAssignmentSuccessful =
      proxyParticipantData?.status === 'confirmed' &&
      validationErrors.length === 0;
  
    if (proxyParticipantData?.status !== 'confirmed') {
      validationErrors.push('代理人の確認が取れていません');
    }
  
    return {
      proxyAssignmentSuccessful,
      originalParticipant,
      proxyParticipant,
      assignmentReason: '会議参加者の代理割り当て',
      assignmentDate,
      validationErrors,
    };
  }
  return { assignProxyParticipant };
})();
