/* AIVIC_FUNCTION_BUNDLE_START owner=validateMeetingAttendance exports=validateMeetingAttendance */
const __aivicBundle_52_validateMeetingAttendance = (() => {
  interface ValidateMeetingAttendanceInput {
    meetingId: string;
    scheduledTime: Date;
    checkTime: Date;
    attendees: Array<{
      memberId: string;
      memberName: string;
      role: string;
      isMandatory: boolean;
      attendanceStatus: 'attending' | 'absent' | 'late' | 'proxy' | string;
      alternativeMemberId: string | null;
      alternativeMemberName: string | null;
    }>;
  }
  
  interface AttendanceWarning {
    type: string;
    memberId: string;
    memberName: string;
    severity: 'critical' | 'warning' | 'info';
    message: string;
  }
  
  interface ValidateMeetingAttendanceResult {
    hasWarning: boolean;
    warningCount: number;
    warnings: AttendanceWarning[];
    shouldNotifyBefore: boolean;
    notificationDeliveryTime: number;
    meetingCanProceeded: boolean;
  }
  
   function validateMeetingAttendance(
    input: ValidateMeetingAttendanceInput
  ): ValidateMeetingAttendanceResult {
    if (input.meetingId === undefined || input.meetingId === null) {
      throw new Error('meetingId is required');
    }
  
    const { scheduledTime, checkTime, attendees } = input;
  
    const warnings: AttendanceWarning[] = [];
    let presentCount = 0;
    let absentCount = 0;
    let lateCount = 0;
    let proxyCount = 0;
  
    for (const attendee of attendees) {
      if (attendee.attendanceStatus === 'attending') {
        presentCount++;
      } else if (attendee.attendanceStatus === 'absent') {
        absentCount++;
        if (
          attendee.isMandatory &&
          !attendee.alternativeMemberId &&
          !attendee.alternativeMemberName
        ) {
          warnings.push({
            type: 'mandatoryAbsentNoAlternative',
            memberId: attendee.memberId,
            memberName: attendee.memberName,
            severity: 'critical',
            message: `${attendee.memberName}が欠席しており、代理参加者がいません。`,
          });
        }
      } else if (attendee.attendanceStatus === 'late') {
        lateCount++;
      } else if (attendee.attendanceStatus === 'proxy') {
        proxyCount++;
      }
    }
  
    const hasWarning = warnings.length > 0;
    const shouldNotifyBefore = hasWarning && checkTime < scheduledTime;
    const notificationDeliveryTime = checkTime.getTime();
    const meetingCanProceeded = !hasWarning;
  
    return {
      hasWarning,
      warningCount: warnings.length,
      warnings,
      shouldNotifyBefore,
      notificationDeliveryTime,
      meetingCanProceeded,
    };
  }
  return { validateMeetingAttendance };
})();
export const validateMeetingAttendance: (...args: any[]) => any = (...args: any[]) => (__aivicBundle_52_validateMeetingAttendance.validateMeetingAttendance as (...args: any[]) => any)(...args);
