/* AIVIC_FUNCTION_BUNDLE_START owner=validateMeetingParticipantAttendance exports=validateMeetingParticipantAttendance */
const __aivicBundle_56_validateMeetingParticipantAttendance = (() => {
  interface ValidateMeetingParticipantAttendanceInput {
    meetingId: string;
    scheduledTime: Date;
    currentTime: Date;
    participants: Array<{
      participantId: string;
      name: string;
      attendanceStatus: string;
      delegateId: string | null;
      delegateName: string | null;
    }>;
  }
  
  interface StatusUpdate {
    participantId: string;
    newStatus: string;
    delegateId?: string;
  }
  
  interface ValidateMeetingParticipantAttendanceResult {
    success?: boolean;
    requiresPostponementJudgment: boolean;
    absentParticipantCount: number;
    assignedDelegateCount: number;
    postponementJudgmentPossible?: boolean;
    onlyDelegateAssignmentApplied?: boolean;
    statusUpdates: StatusUpdate[];
    errorMessage?: string;
    unassignedAbsentParticipants?: string[];
  }
  
   function validateMeetingParticipantAttendance(
    input: ValidateMeetingParticipantAttendanceInput
  ): ValidateMeetingParticipantAttendanceResult {
    if (!input.meetingId || input.meetingId.trim() === '') {
      throw new Error("meetingId is required");
    }
  
    const { scheduledTime, currentTime, participants } = input;
  
    const timeUntilMeeting = scheduledTime.getTime() - currentTime.getTime();
    const hoursUntilMeeting = timeUntilMeeting / (1000 * 60 * 60);
    const isWithin24Hours = hoursUntilMeeting <= 24 && hoursUntilMeeting > 0;
  
    const absentParticipants = participants.filter(
      (p) => p.attendanceStatus === 'absent'
    );
    const absentParticipantCount = absentParticipants.length;
  
    const assignedAbsentParticipants = absentParticipants.filter(
      (p) => p.delegateId !== null && p.delegateId !== undefined
    );
    const assignedDelegateCount = assignedAbsentParticipants.length;
  
    const unassignedAbsentParticipants = absentParticipants
      .filter((p) => p.delegateId === null || p.delegateId === undefined)
      .map((p) => p.participantId);
  
    const statusUpdates: StatusUpdate[] = assignedAbsentParticipants.map((p) => ({
      participantId: p.participantId,
      newStatus: 'absent_with_delegate',
      delegateId: p.delegateId!,
    }));
  
    // ケース: 全員出席
    if (absentParticipantCount === 0) {
      return {
        success: true,
        requiresPostponementJudgment: false,
        absentParticipantCount: 0,
        assignedDelegateCount: 0,
        statusUpdates: [],
      };
    }
  
    // ケース: 24時間以内の会議
    if (isWithin24Hours) {
      // 全員に代理者が指定されている場合
      if (unassignedAbsentParticipants.length === 0) {
        return {
          requiresPostponementJudgment: true,
          absentParticipantCount,
          assignedDelegateCount,
          postponementJudgmentPossible: true,
          statusUpdates,
        };
      }
  
      // 一部に代理者が未指定の場合
      const errorMessage = `代理者未指定: ${unassignedAbsentParticipants.join(', ')}`;
      return {
        requiresPostponementJudgment: true,
        absentParticipantCount,
        assignedDelegateCount,
        postponementJudgmentPossible: false,
        errorMessage,
        unassignedAbsentParticipants,
        statusUpdates: [],
      };
    }
  
    // ケース: 24時間を超える会議
    // 全員に代理者が指定されている場合
    if (unassignedAbsentParticipants.length === 0) {
      return {
        requiresPostponementJudgment: false,
        onlyDelegateAssignmentApplied: true,
        absentParticipantCount,
        assignedDelegateCount,
        statusUpdates,
      };
    }
  
    // 一部に代理者が未指定の場合
    const errorMessage = `代理者未指定: ${unassignedAbsentParticipants.join(', ')}`;
    return {
      success: false,
      requiresPostponementJudgment: false,
      absentParticipantCount,
      assignedDelegateCount,
      errorMessage,
      unassignedAbsentParticipants,
      statusUpdates: [],
    };
  }
  return { validateMeetingParticipantAttendance };
})();
export const validateMeetingParticipantAttendance: (...args: any[]) => any = (...args: any[]) => (__aivicBundle_56_validateMeetingParticipantAttendance.validateMeetingParticipantAttendance as (...args: any[]) => any)(...args);
